<?php
require_once __DIR__.'/includes/panel_helpers.php'; exigirRol([1]);
if(empty($_SESSION['csrf_token'])) $_SESSION['csrf_token']=bin2hex(random_bytes(32));
require_once __DIR__.'/../config/database.php';
$usuarios=[];$roles=[];$medicos=[];$pacientes=[];
try{
    $pdo=conectarBD();
    $usuarios=$pdo->query("SELECT u.id,u.nombre_usuario,u.nombre,u.correo,u.activo,r.nombre rol,i.expira_at,i.usado_at FROM usuarios u JOIN roles r ON r.id=u.rol_id LEFT JOIN LATERAL (SELECT expira_at,usado_at FROM invitaciones_usuario WHERE usuario_id=u.id ORDER BY id DESC LIMIT 1) i ON TRUE ORDER BY u.id")->fetchAll();
    $roles=$pdo->query("SELECT id,nombre FROM roles ORDER BY id")->fetchAll();
    $medicos=$pdo->query("SELECT id,nombres,apellidos FROM medicos WHERE activo=TRUE AND usuario_id IS NULL ORDER BY apellidos,nombres")->fetchAll();
    $pacientes=$pdo->query("SELECT id,nombres,apellidos,documento_identidad FROM pacientes WHERE activo=TRUE AND usuario_id IS NULL ORDER BY apellidos,nombres")->fetchAll();
}catch(Throwable $e){error_log($e->getMessage());$error='No se pudo cargar la administración de usuarios. Verifica que la migración de invitaciones esté instalada.';}
require_once __DIR__.'/includes/layout.php';renderSidebar('usuarios');
?>
<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:16px;flex-wrap:wrap;margin-bottom:24px"><div><h1 style="font-size:28px;font-weight:700">Usuarios e invitaciones</h1><p style="color:var(--color-text-light)">Crea cuentas y permite que cada persona defina su contraseña.</p></div><a href="#nueva-invitacion" class="btn btn-primary">Nueva invitación</a></div>
<?php if(isset($error)): ?><div class="alert alert-error"><?= htmlspecialchars($error) ?></div><?php endif; ?>
<?php if(isset($_GET['error'])): $errores=['datos'=>'Revisa los datos ingresados.','vinculo'=>'Debes seleccionar una ficha disponible para ese rol.','rol'=>'El rol seleccionado no existe.','duplicado'=>'El usuario o correo ya está registrado.','servidor'=>'No se pudo crear la invitación.']; ?><div class="alert alert-error"><?= htmlspecialchars($errores[$_GET['error']]??'No se pudo crear la invitación.') ?></div><?php endif; ?>
<?php if(isset($_GET['creada'])): ?><div class="alert alert-success">Invitación creada. El enlace se muestra una sola vez debajo.</div><?php endif; ?>
<?php if(!empty($_SESSION['invitacion_link'])): $enlace=$_SESSION['invitacion_link'];unset($_SESSION['invitacion_link']); ?>
<div class="card"><div class="card-header"><h2 class="card-title">Enlace de activación</h2></div><div class="card-body"><p style="margin-bottom:12px">Copia este enlace y entrégaselo solamente a la persona invitada. Caduca en 72 horas.</p><div style="display:flex;gap:10px;flex-wrap:wrap"><input id="invitation-link" class="form-input" style="flex:1;min-width:260px" readonly value="<?= htmlspecialchars($enlace) ?>"><button type="button" class="btn btn-primary" onclick="navigator.clipboard.writeText(document.getElementById('invitation-link').value);this.textContent='Copiado'">Copiar enlace</button></div></div></div>
<?php endif; ?>
<div class="card" id="nueva-invitacion"><div class="card-header"><h2 class="card-title">Crear cuenta pendiente</h2></div><div class="card-body">
<form method="POST" action="guardar_invitacion.php"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($_SESSION['csrf_token']) ?>"><div class="form-grid"><div class="form-group"><label class="form-label required">Nombre completo</label><input class="form-input" name="nombre" required maxlength="120"></div><div class="form-group"><label class="form-label required">Nombre de usuario</label><input class="form-input" name="nombre_usuario" required maxlength="80" pattern="[A-Za-z0-9._-]+"></div><div class="form-group"><label class="form-label">Correo</label><input class="form-input" type="email" name="correo" maxlength="255"></div><div class="form-group"><label class="form-label required">Rol</label><select class="form-select" name="rol_id" id="invite-role" required><option value="">Seleccionar rol</option><?php foreach($roles as $r): ?><option value="<?= (int)$r['id'] ?>"><?= ucfirst(htmlspecialchars($r['nombre'])) ?></option><?php endforeach; ?></select></div></div>
<div class="form-grid"><div class="form-group" id="doctor-link" hidden><label class="form-label">Vincular médico</label><select class="form-select" name="medico_id"><option value="">Seleccionar médico</option><?php foreach($medicos as $m): ?><option value="<?= (int)$m['id'] ?>"><?= htmlspecialchars($m['apellidos'].', '.$m['nombres']) ?></option><?php endforeach; ?></select></div><div class="form-group" id="patient-link" hidden><label class="form-label">Vincular paciente</label><select class="form-select" name="paciente_id"><option value="">Seleccionar paciente</option><?php foreach($pacientes as $p): ?><option value="<?= (int)$p['id'] ?>"><?= htmlspecialchars($p['apellidos'].', '.$p['nombres'].' - '.($p['documento_identidad']??'Sin CI')) ?></option><?php endforeach; ?></select></div></div>
<button class="btn btn-primary" type="submit">Crear invitación</button></form></div></div>
<div class="card"><div class="card-header"><h2 class="card-title">Cuentas registradas</h2></div><div class="card-body" style="padding:0"><div class="table-container"><table class="table"><thead><tr><th>Usuario</th><th>Nombre</th><th>Rol</th><th>Estado</th><th>Invitación</th></tr></thead><tbody><?php foreach($usuarios as $u): ?><tr><td><?= htmlspecialchars($u['nombre_usuario']??'-') ?></td><td><?= htmlspecialchars($u['nombre']) ?></td><td><?= ucfirst(htmlspecialchars($u['rol'])) ?></td><td><span class="badge badge-<?= $u['activo']?'success':'warning' ?>"><?= $u['activo']?'Activa':'Pendiente' ?></span></td><td><?= $u['usado_at']?'Utilizada':($u['expira_at']?(strtotime($u['expira_at'])<time()?'Caducada':'Vigente'):'-') ?></td></tr><?php endforeach; ?></tbody></table></div></div></div>
<script>document.addEventListener('DOMContentLoaded',()=>{const role=document.getElementById('invite-role'),doctor=document.getElementById('doctor-link'),patient=document.getElementById('patient-link');const update=()=>{doctor.hidden=role.value!=='3';patient.hidden=role.value!=='4'};role.addEventListener('change',update);update()});</script>
<?php renderFooter(); ?>
